const {createRequire}=require('node:module');
const {writeFileSync,mkdirSync}=require('node:fs');
const {join}=require('node:path');
const root=process.argv[2],out=process.argv[3];mkdirSync(out,{recursive:true});
const load=createRequire(join(root,'test/index.js'));const playwright=load('@playwright/test');
const sessions=new Map();let counter=0;
const originalLaunch=playwright._electron.launch.bind(playwright._electron);
playwright._electron.launch=async options=>{
 const app=await originalLaunch(options),state={index:++counter,start:Date.now(),renderers:[]};sessions.set(app,state);
 try {await app.evaluate(async()=>{const {Session}=process.getBuiltinModule('node:inspector');const session=new Session();session.connect();globalThis.__ipcOptResumeProfile={session,post:(name,params={})=>new Promise((resolve,reject)=>session.post(name,params,(e,r)=>e?reject(e):resolve(r)))};await globalThis.__ipcOptResumeProfile.post('Profiler.enable');await globalThis.__ipcOptResumeProfile.post('Profiler.start');});}catch(error){state.mainError=String(error);}

 const port=Number(process.env.IPC_OPT_EXT_INSPECT_PORT);
 if(port)state.extConnecting=(async()=>{
  for(let attempt=0;attempt<300&&!state.stopped;attempt++){
   try{
    const targets=await(await fetch(`http://127.0.0.1:${port}/json/list`)).json();
    const ws=new WebSocket(targets[0].webSocketDebuggerUrl);await new Promise((resolve,reject)=>{ws.addEventListener('open',resolve,{once:true});ws.addEventListener('error',reject,{once:true});});
    let next=0;const pending=new Map();ws.addEventListener('message',e=>{const m=JSON.parse(e.data);if(m.id){const p=pending.get(m.id);if(p){pending.delete(m.id);m.error?p.reject(new Error(JSON.stringify(m.error))):p.resolve(m.result);}}});
    const post=(method,params={})=>new Promise((resolve,reject)=>{const id=++next;pending.set(id,{resolve,reject});ws.send(JSON.stringify({id,method,params}));});
    const check=await post('Runtime.evaluate',{expression:'JSON.stringify({pid:process.pid,ppid:process.ppid})',returnByValue:true});const owner=JSON.parse(check.result.value);
    if(owner.ppid!==app.process().pid){ws.close();throw new Error('Inspector does not belong to this smoke application');}
    await post('Profiler.enable');await post('Profiler.start');state.ext={ws,post,owner};return;
   }catch(error){state.extLastError=String(error);await new Promise(resolve=>setTimeout(resolve,100));}
  }
 })();

 const attach=async page=>{try{const cdp=await page.context().newCDPSession(page);await cdp.send('Profiler.enable');await cdp.send('Profiler.start');state.renderers.push({cdp,url:page.url()});}catch(error){(state.errors??=[]).push(String(error));}};
 app.on('window',attach);await Promise.all(app.windows().map(attach));return app;
};
const {PlaywrightDriver}=load(join(root,'../automation/out/playwrightDriver.js'));const originalClose=PlaywrightDriver.prototype.close;
PlaywrightDriver.prototype.close=async function(){
 const state=sessions.get(this.application);if(state&&!state.stopped){state.stopped=true;
  if(state.ext){try{const snapshot=await state.ext.post('Runtime.evaluate',{expression:'JSON.stringify(globalThis.__ipcOptRpcStats||null)',returnByValue:true});writeFileSync(join(out,`launch-${state.index}-extension-host-rpc.json`),snapshot.result.value);const {profile}=await state.ext.post('Profiler.stop');writeFileSync(join(out,`launch-${state.index}-extension-host.cpuprofile`),JSON.stringify(profile));state.ext.ws.close();}catch(error){state.extLastError=String(error);}}
  for(const [i,r] of state.renderers.entries()){try{const snapshot=await r.cdp.send('Runtime.evaluate',{expression:'JSON.stringify(globalThis.__ipcOptRpcStats||null)',returnByValue:true});writeFileSync(join(out,`launch-${state.index}-renderer-${i}-rpc.json`),snapshot.result.value);const {profile}=await r.cdp.send('Profiler.stop');writeFileSync(join(out,`launch-${state.index}-renderer-${i}.cpuprofile`),JSON.stringify(profile));}catch(error){(state.errors??=[]).push(String(error));}}
  try{const profile=await this.application.evaluate(async()=>{const p=globalThis.__ipcOptResumeProfile;if(!p)return null;const r=await p.post('Profiler.stop');p.session.disconnect();delete globalThis.__ipcOptResumeProfile;return r.profile;});if(profile)writeFileSync(join(out,`launch-${state.index}-main.cpuprofile`),JSON.stringify(profile));}catch(error){(state.errors??=[]).push(String(error));}
  writeFileSync(join(out,`launch-${state.index}-metadata.json`),JSON.stringify({...state,extConnecting:undefined,ext:state.ext?{owner:state.ext.owner}:undefined,renderers:state.renderers.map(r=>({url:r.url})),end:Date.now()},null,2));
 }
 return originalClose.call(this);
};
const Mocha=load('mocha');const mocha=new Mocha({timeout:120000,retries:0,reporter:'spec',failZero:true});mocha.addFile(join(root,'out/main.js'));mocha.loadFiles();mocha.grep('Data Loss \\(insiders -> insiders\\).*verifies opened editors are restored|Chat Sessions.*Test Copilot CLI session$');
const tests=[];let pending=0,retried=false;const runner=mocha.run(failures=>{writeFileSync(join(out,'functional-report.json'),JSON.stringify({tests,pending,failures,retried,diagnosticOnly:true,profiled:true}));process.exit(failures||retried||!tests.length?1:0);});runner.on('pass',test=>tests.push(test.fullTitle()));runner.on('pending',()=>pending++);runner.on('retry',()=>retried=true);

