from pathlib import Path
import json,collections,statistics
root=Path('/tmp/ipc-opt-resume-20261023/profile-rpc-stats');rows=[]
for path in sorted(root.glob('*-rpc.json')):
 data=json.loads(path.read_text());summary=collections.Counter();latencies=collections.defaultdict(list)
 if not data:continue
 for protocol in data['protocols']:
  pending={}
  for timestamp,direction,length,req,initiator,text in protocol['entries']:
   summary[direction+' '+text]+=1
   if direction=='out' and text.startswith('request: '):pending[req]=(timestamp,text[9:])
   if direction=='in' and text.startswith(('receiveReply:','receiveReplyErr:')) and req in pending:
    start,method=pending.pop(req);latencies[method].append(timestamp-start)
 one={'file':path.name,'protocols':len(data['protocols']),'events':dict(summary),'roundTrips':{name:{'count':len(v),'medianMs':statistics.median(v),'maxMs':max(v),'sumMs':sum(v)} for name,v in latencies.items()}};rows.append(one);print('\n',path.name,'events',sum(summary.values()),'protocols',len(data['protocols']))
 print('Most frequent request/notification sends:',[(k,v) for k,v in summary.most_common() if k.startswith('out request') or k.startswith('out notification')][:8])
 print('Longest observed round trips (include remote handler time):',sorted(one['roundTrips'].items(),key=lambda x:x[1]['maxMs'],reverse=True)[:6])
(root.parent/'rpc-stats-summary.json').write_text(json.dumps(rows,indent=2)+'\n')
